package com.fitmind.controller; import com.fitmind.common.*; import com.fitmind.dto.WeightRecordRequest; import com.fitmind.entity.WeightRecord; import com.fitmind.service.WeightService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import javax.validation.Valid; import javax.validation.constraints.*; import java.util.List;
@RestController @RequestMapping("/api/weights") @RequiredArgsConstructor public class WeightController { private final WeightService service; @GetMapping public Result<PageResult<WeightRecord>> page(@RequestParam(defaultValue="1") @Min(1) long page,@RequestParam(defaultValue="5") @Min(1) @Max(100) long size){return Result.ok(service.page(page,size));} @GetMapping("/trend") public Result<List<WeightRecord>> trend(@RequestParam(defaultValue="7") int days){return Result.ok(service.trend(days));} @PostMapping public Result<WeightRecord> create(@Valid @RequestBody WeightRecordRequest r){return Result.ok(service.create(r));} @PutMapping("/{id}") public Result<WeightRecord> update(@PathVariable long id,@Valid @RequestBody WeightRecordRequest r){return Result.ok(service.update(id,r));} @DeleteMapping("/{id}") public Result<Void> delete(@PathVariable long id){service.delete(id);return Result.ok();} }
